#!/usr/bin/env bash
set -euo pipefail

ROOT="${PYSTAMPS_ROOT:-/home/ubuntu/software/pystamps-main}"
DATASET="${REAL_DATASET:-/mnt/vol-gdc28n1r/insar/cangzhou_P69/pystamps_sbas_ps_optimized}"

PORTED="$ROOT/pystamps/pipeline/ported.py"
MODULE="$ROOT/pystamps/pipeline/stage6_sbas.py"
TEST_FILE="$ROOT/tests/test_stage6_sbas.py"
RUNNER="$ROOT/run_stage6_sbas.sh"
NATIVE_RUNNER="$ROOT/run_native_stage.sh"

cd "$ROOT"

for path in "$PORTED" "$ROOT/pystamps/io/mat.py"; do
    [[ -f "$path" ]] || {
        echo "缺少文件：$path" >&2
        exit 2
    }
done

if pgrep -af 'pystamps-native.*stage.*6|pystamps run.*--start-step[ =]6|stage6_sbas' >/dev/null 2>&1; then
    echo "检测到Stage 6进程仍在运行，拒绝修改。" >&2
    pgrep -af 'pystamps-native.*stage.*6|pystamps run.*--start-step[ =]6|stage6_sbas' || true
    exit 3
fi

STAMP="$(date +%Y%m%d_%H%M%S)"
BACKUP="$ROOT/.stage6_sbas_backup/$STAMP"
mkdir -p "$BACKUP/pystamps/pipeline" "$BACKUP/tests"

cp -a "$PORTED" "$BACKUP/pystamps/pipeline/ported.py"
[[ -f "$MODULE" ]] && cp -a "$MODULE" "$BACKUP/pystamps/pipeline/stage6_sbas.py"
[[ -f "$TEST_FILE" ]] && cp -a "$TEST_FILE" "$BACKUP/tests/test_stage6_sbas.py"
[[ -f "$NATIVE_RUNNER" ]] && cp -a "$NATIVE_RUNNER" "$BACKUP/run_native_stage.sh"

echo "$BACKUP" > "$ROOT/.stage6_sbas_last_backup"

python - <<'PY'
from pathlib import Path
import base64

root = Path("/home/ubuntu/software/pystamps-main")
root.joinpath("pystamps/pipeline/stage6_sbas.py").write_bytes(
    base64.b64decode("")
)
root.joinpath("tests/test_stage6_sbas.py").write_bytes(
    base64.b64decode("")
)

ported_path = root / "pystamps/pipeline/ported.py"
text = ported_path.read_text(encoding="utf-8")
marker = "# === STAGE6_SBAS_WRAPPER_V1 ==="

if marker not in text:
    wrapper = base64.b64decode("").decode("utf-8")
    ported_path.write_text(
        text.rstrip() + "\n\n" + wrapper.lstrip(),
        encoding="utf-8",
    )
    print("已追加Stage 6 SBAS调度器。")
else:
    print("Stage 6 SBAS调度器已经存在。")
PY

cat > "$RUNNER" <<'BASH_RUN'
#!/usr/bin/env bash
set -euo pipefail

ROOT="${PYSTAMPS_ROOT:-/home/ubuntu/software/pystamps-main}"
DATASET="${REAL_DATASET:-/mnt/vol-gdc28n1r/insar/cangzhou_P69/pystamps_sbas_ps_optimized}"

export PYTHONUNBUFFERED=1
export OMP_NUM_THREADS="${OMP_NUM_THREADS:-1}"
export OPENBLAS_NUM_THREADS="${OPENBLAS_NUM_THREADS:-1}"
export MKL_NUM_THREADS="${MKL_NUM_THREADS:-1}"
export NUMEXPR_NUM_THREADS="${NUMEXPR_NUM_THREADS:-1}"

export PYSTAMPS_SBAS_PROGRESS="${PYSTAMPS_SBAS_PROGRESS:-1}"
export PYSTAMPS_SBAS_EDGE_CHUNK="${PYSTAMPS_SBAS_EDGE_CHUNK:-512}"
export PYSTAMPS_STAGE6_SNAPHU_WORKERS="${PYSTAMPS_STAGE6_SNAPHU_WORKERS:-4}"
export PYSTAMPS_SBAS_ANNEAL_WORKERS="${PYSTAMPS_SBAS_ANNEAL_WORKERS:-8}"
export PYSTAMPS_SBAS_ANNEAL_RUNS="${PYSTAMPS_SBAS_ANNEAL_RUNS:-15}"
export PYSTAMPS_SBAS_STRICT_ANNEAL="${PYSTAMPS_SBAS_STRICT_ANNEAL:-1}"
export PYSTAMPS_SBAS_KEEP_WORK="${PYSTAMPS_SBAS_KEEP_WORK:-0}"

cd "$ROOT"

echo "============================================================"
echo "StaMPS-compatible SBAS Stage 6"
echo "Dataset       : $DATASET"
echo "Edge chunk    : $PYSTAMPS_SBAS_EDGE_CHUNK"
echo "SNAPHU workers: $PYSTAMPS_STAGE6_SNAPHU_WORKERS"
echo "Anneal workers: $PYSTAMPS_SBAS_ANNEAL_WORKERS"
echo "Anneal runs   : $PYSTAMPS_SBAS_ANNEAL_RUNS"
echo "Strict anneal : $PYSTAMPS_SBAS_STRICT_ANNEAL"
echo "============================================================"

python -m pystamps.pipeline.stage6_sbas \
    --dataset "$DATASET" \
    --io-workers "${PYSTAMPS_STAGE6_GRID_WORKERS:-8}" \
    "$@"
BASH_RUN

chmod +x "$RUNNER"

if [[ -f "$NATIVE_RUNNER" ]]; then
python - <<'PY'
from pathlib import Path

path = Path("/home/ubuntu/software/pystamps-main/run_native_stage.sh")
text = path.read_text(encoding="utf-8")
marker = "# STAGE6_SBAS_DELEGATE_V1"

if marker in text:
    print("run_native_stage.sh已经包含SBAS委派。")
else:
    anchor = "    6)\n"
    if anchor not in text:
        raise SystemExit("未找到run_native_stage.sh的Stage 6 case，未自动修改。")

    lines = [
        "    6)",
        "        # STAGE6_SBAS_DELEGATE_V1",
        "        if python - \"$DATASET\" <<'PY_CHECK'",
        "from pathlib import Path",
        "import sys",
        "import numpy as np",
        "from pystamps.io.mat import read_mat_variables",
        "",
        "root = Path(sys.argv[1])",
        "payload = read_mat_variables(root / \"parms.mat\", (\"small_baseline_flag\",))",
        "value = payload.get(\"small_baseline_flag\", \"n\")",
        "text = \"\".join(str(v) for v in np.asarray(value).reshape(-1)).strip().lower()",
        "raise SystemExit(0 if text == \"y\" else 1)",
        "PY_CHECK",
        "        then",
        "            exec bash \"$ROOT/run_stage6_sbas.sh\"",
        "        fi",
        "",
    ]
    delegate = "\n".join(lines)
    text = text.replace(anchor, delegate, 1)
    path.write_text(text, encoding="utf-8")
    print("已让run_native_stage.sh在SBAS数据上自动调用run_stage6_sbas.sh。")
PY
fi

cat > "$ROOT/rollback_stage6_sbas_patch.sh" <<'BASH_ROLLBACK'
#!/usr/bin/env bash
set -euo pipefail

ROOT="${PYSTAMPS_ROOT:-/home/ubuntu/software/pystamps-main}"
RECORD="$ROOT/.stage6_sbas_last_backup"

[[ -f "$RECORD" ]] || {
    echo "找不到Stage 6 SBAS备份记录。" >&2
    exit 2
}

BACKUP="$(cat "$RECORD")"
[[ -d "$BACKUP" ]] || {
    echo "备份目录不存在：$BACKUP" >&2
    exit 2
}

cp -a "$BACKUP/pystamps/pipeline/ported.py" \
      "$ROOT/pystamps/pipeline/ported.py"

if [[ -f "$BACKUP/pystamps/pipeline/stage6_sbas.py" ]]; then
    cp -a "$BACKUP/pystamps/pipeline/stage6_sbas.py" \
          "$ROOT/pystamps/pipeline/stage6_sbas.py"
else
    rm -f "$ROOT/pystamps/pipeline/stage6_sbas.py"
fi

if [[ -f "$BACKUP/tests/test_stage6_sbas.py" ]]; then
    cp -a "$BACKUP/tests/test_stage6_sbas.py" \
          "$ROOT/tests/test_stage6_sbas.py"
else
    rm -f "$ROOT/tests/test_stage6_sbas.py"
fi

if [[ -f "$BACKUP/run_native_stage.sh" ]]; then
    cp -a "$BACKUP/run_native_stage.sh" \
          "$ROOT/run_native_stage.sh"
fi

rm -f "$ROOT/run_stage6_sbas.sh"

echo "已恢复：$BACKUP"
BASH_ROLLBACK

chmod +x "$ROOT/rollback_stage6_sbas_patch.sh"

python -m py_compile \
    "$MODULE" \
    "$PORTED"

bash -n "$RUNNER"
[[ ! -f "$NATIVE_RUNNER" ]] || bash -n "$NATIVE_RUNNER"

python -m pytest -q "$TEST_FILE"

echo
echo "================ 真实数据预检 ================"
python -m pystamps.pipeline.stage6_sbas \
    --dataset "$DATASET" \
    --preflight

echo
echo "============================================================"
echo "Stage 6 SBAS补丁安装完成"
echo "备份：$BACKUP"
echo
echo "正式运行："
echo "  bash $RUNNER"
echo
echo "也可以继续使用："
echo "  bash $NATIVE_RUNNER 6"
echo "============================================================"

if [[ "${RUN_STAGE6_NOW:-0}" == "1" ]]; then
    exec bash "$RUNNER"
fi